0a35645f54555793d91788a6c5c0e9e39aa98c28:
query InstallPageQuery(
  $id: ID!
) {
  node(id: $id) {
    __typename
    ... on Install {
      client
      environment
      cloud
      region
      channel
      pinnedVersion
      health
      chartVersion
      lastSeenAt
      createdBy {
        label
      }
      createdAt
      retiredAt
      retiredBy {
        label
      }
      services {
        name
        version
        imageDigest
        replicasReady
        replicasDesired
        restarts24h
        healthy
      }
      metrics {
        decisionsPerSecond
        pdpP99Ms
        errorRate
        kafkaLag
        clickhouseDiskUsedPercent
      }
      versionHistory {
        chartVersion
        firstSeenAt
      }
    }
    id
  }
}

13d994fa913a0e4aeac508f06a5007a896647660:
query InstallChartsQuery(
  $id: ID!
  $window: MetricWindow!
) {
  node(id: $id) {
    __typename
    ... on Install {
      metricHistory(window: $window) {
        at
        decisionsPerSecond
        pdpP99Ms
        errorRate
        kafkaLag
        clickhouseDiskUsedPercent
        containmentFeedAgeSeconds
        policySyncAgeSeconds
        principalsSyncAgeSeconds
        connectorSyncAgeSeconds
        gatewayPdpUnreachable
        degraded
      }
    }
    id
  }
}

2c4d5141282284cb7703d1051df1d05f1b07ecd4:
mutation InstallPageRetireMutation(
  $input: RetireInstallInput!
) {
  retireInstall(input: $input) {
    install {
      id
      retiredAt
    }
  }
}

8341a9fa1f0c8e893f8ab924ec991c698957f63d:
query FleetPageQuery {
  installs(first: 200) {
    edges {
      node {
        id
        client
        environment
        cloud
        region
        channel
        pinnedVersion
        health
        chartVersion
        lastSeenAt
        services {
          healthy
        }
        metrics {
          decisionsPerSecond
          pdpP99Ms
        }
      }
    }
  }
}

abd083120fcbb19ca7dfe9c294b8c36cec5356fd:
mutation FleetPageRegisterMutation(
  $input: RegisterInstallInput!
) {
  registerInstall(input: $input) {
    install {
      id
    }
    reportingToken
    pullToken
  }
}

b5c697674e42f5b45e5745129b1bc493c02cf123:
query ReleasesPageQuery {
  releases {
    version
    installCount
    installs {
      id
      client
      environment
      channel
      pinnedVersion
      health
    }
  }
}
